/// <summary>
/// Extension for TAMRebateGroup form
/// </summary>
[ExtensionOf(formStr(TAMRebateGroup))]
internal final class METTAMRebateGroupForm_Extension
{
}

Method.Source:
    /// <summary>
    /// Override JumpRef method for the METGUPProductPricingAttributeGroup
    /// This to open up the GUPPricingAttributeGroupProduct instead of the GUPPricingAttributeGroup form
    /// </summary>
    /// <param name = "_formControl">formControl</param>
    public void METJumpRef_PricingAttributeGroup(FormControl _formControl)
    {
        TAMRebateGroup  tamRebateGroup  = _formControl.formRun().dataSource(formDataSourceStr(TAMRebateGroup,TAMRebateGroup)).cursor() as TAMRebateGroup;

        if(tamRebateGroup.METGUPProductPricingAttributeGroup)
        {
            GUPPricingAttributeGroup    gupPricingAttributeGroup;
            select firstonly gupPricingAttributeGroup
                where gupPricingAttributeGroup.GroupType == GUPPricingAttributeGroupType::Product
                && gupPricingAttributeGroup.Name == tamRebateGroup.METGUPProductPricingAttributeGroup;

            Args        	args = new Args();
            if (gupPricingAttributeGroup.RecId)
            {
                args.record(gupPricingAttributeGroup);
                args.lookupRecord(gupPricingAttributeGroup);
            }
            MenuFunction menuFunction = new MenuFunction(menuitemDisplayStr(GUPPricingAttributeGroupProduct), MenuItemType::Display);
            menuFunction.run(args);
        }
    }
